    m: size,
    n: size,
    A: DATA_TYPE[m, n] @ DRAM,
    x: DATA_TYPE[n] @ DRAM,
    y: DATA_TYPE[n] @ DRAM,
    tmp: DATA_TYPE[m] @ DRAM,
):
    # We operate on the full matrix/vector domains [0, m) and [0, n).
    assert m >= 0
    assert n >= 0

    # ------------------------------------------------------------------
    # Phase 1: tmp = A * x        (matrix–vector product)
    # ------------------------------------------------------------------
    # For each row i, compute a dot-product between row A[i, :] and x[:].
    # This keeps the inner loop over j contiguous in memory (row‑major A,
    # contiguous x), which is friendly to the C compiler's auto‑vectorizer.
    for i in seq(0, m):
        tmp[i] = 0.0
        for j in seq(0, n):
            tmp[i] += A[i, j] * x[j]

    # At this point:
    #   tmp[i] = sum_{j=0..n-1} A[i, j] * x[j]   for all i in [0, m).

    # ------------------------------------------------------------------
    # Phase 2: y = A^T * tmp      (second matrix–vector product)
    # ------------------------------------------------------------------
    # Mathematically, starting from y ≡ 0, the original kernel does:
    #
    #   for i in 0..m-1:
    #     ... compute tmp[i] ...
    #     for j in 0..n-1:
    #       y[j] += A[i, j] * tmp[i]
