from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM
from exo.frontend.syntax import *

# Baseline ATAX kernel, written to closely match the mathematical
# definition:
#
#   tmp[i] = sum_j A[i, j] * x[j]          for i in [0, m)
#   y[j]   = sum_i A[i, j] * tmp[i]        for j in [0, n)
#
# with y initially zero. This is algebraically equivalent to the original
# fused implementation (y = A^T * (A * x)), but expressed in two clean
# matrix–vector products so that we can schedule them independently.

@proc
def kernel_atax_base(
    m: size,
    n: size,
    A: DATA_TYPE[m, n] @ DRAM,
    x: DATA_TYPE[n] @ DRAM,
    y: DATA_TYPE[n] @ DRAM,
    tmp: DATA_TYPE[m] @ DRAM,
):
    # Initialize y to zero (live-out vector)
    for j in seq(0, n):
        y[j] = 0.0

    # Fused computation as in the original kernel:
    #   tmp[i] = sum_j A[i, j] * x[j]
    #   y[j]  += A[i, j] * tmp[i]
    #
    # We will later use scheduling primitives to fission this loop
    # into two phases so that tmp = A * x can be parallelized
    # independently of y = A^T * tmp.
    for i in seq(0, m):
        tmp[i] = 0.0
        for j in seq(0, n):
            tmp[i] += A[i, j] * x[j]
        for j in seq(0, n):
            y[j] += A[i, j] * tmp[i]


# -------------------------
# Scheduling / optimization
# -------------------------

p = kernel_atax_base

# 1) Loop fission on the body of the i-loop.
#
# We split the single outer loop over i into:
#   Phase 1: tmp[i] = sum_j A[i, j] * x[j]
#   Phase 2: y[j]  += A[i, j] * tmp[i]
#
# This is semantics-preserving because:
#   - tmp[i] is written and then only read in the j-loop for the same i;
#   - y is initialized before both phases and only accumulated into.
i_loop = p.find_loop("i")
i_body = i_loop.body()
# i_body[0]: tmp[i] = 0.0
# i_body[1]: for j in seq(0, n): tmp[i] += ...
# i_body[2]: for j in seq(0, n): y[j]   += ...
split_point = i_body[2].before()
p = fission(p, split_point)

# After fission, the relevant part of the kernel is:
#   for i in seq(0, m):
#       tmp[i] = 0.0
#       for j in seq(0, n):
#           tmp[i] += A[i, j] * x[j]
#   for i in seq(0, m):
#       for j in seq(0, n):
#           y[j] += A[i, j] * tmp[i]


# 2) Parallelize the first i-loop (Phase 1: tmp = A * x).
#
# Each tmp[i] depends only on row i of A and on the read-only vector x.
# Different values of i write disjoint elements of tmp, so the loop
# carries no cross-iteration dependencies and is safe to parallelize.
tmp_i_loop = p.find_loop("i #0")
p = parallelize_loop(p, tmp_i_loop)

