tmp_i_loop = p.find_loop("i #0")
tmp_body = tmp_i_loop.body()
# tmp_body[0]: tmp[i] = 0.0
# tmp_body[1]: for j in seq(0, n): tmp[i] += ...
j_tmp = tmp_body[1]
p = divide_loop(p, j_tmp, TILE_J, ("jo", "ji"), tail="guard")

