# hardware prefetcher and makes it easier for the downstream C compiler
# to auto-vectorize.
y_i_loop = p.find_loop("i #1")
y_body = y_i_loop.body()
# y_body[0]: for j in seq(0, n): y[j] += ...
j_y = y_body[0]
p = divide_loop(p, j_y, TILE_J, ("jo2", "ji2"), tail="guard")

# The final optimized kernel that will be code-generated and called
# from C is bound to the name expected by the driver.
kernel_atax = p
